<?php
declare(strict_types=1);
namespace CardPay\Tests\Integration;
use CardPay\Core\Request;use CardPay\Services\ApiAuthService;use CardPay\Services\DeviceAuthService;use CardPay\Tests\TestCase;
final class AuthAndWebhookTest extends TestCase
{
    public function test_valid_hmac_authenticates_and_replay_is_rejected():void{$timestamp=(string)time();$nonce='nonce-1234567890';$body='{"amount":1000}';$base=new Request('POST','/api/v1/payments',$body,[],[],[],[],'127.0.0.1','');$signature=hash_hmac('sha256',ApiAuthService::canonical($base,$timestamp,$nonce),$this->appSecret);$request=new Request('POST','/api/v1/payments',$body,[],[],[],['x-cardpay-key'=>$this->application['public_key'],'x-cardpay-timestamp'=>$timestamp,'x-cardpay-nonce'=>$nonce,'x-cardpay-signature'=>$signature],'127.0.0.1','');$auth=new ApiAuthService($this->db,$this->apps,$this->crypto,$this->config);self::assertSame($this->application['id'],$auth->authenticate($request)['id']);$this->expectException(\CardPay\Core\DomainException::class);$auth->authenticate($request);}
    public function test_shortcut_secret_authenticates_without_hmac():void{$request=new Request('POST','/api/v1/devices/shortcut-sms','{}',[],[],[],['x-device-key'=>$this->device['device_key'],'x-device-secret'=>$this->deviceSecret],'127.0.0.1','');$auth=new DeviceAuthService($this->db,$this->devices,$this->crypto,$this->config);$authenticated=$auth->authenticateShortcut($request);self::assertSame($this->device['id'],$authenticated['id']);self::assertArrayNotHasKey('device_secret_encrypted',$authenticated);}
    public function test_shortcut_secret_authenticates_from_json_body():void{$body=json_encode(['device_key'=>$this->device['device_key'],'device_secret'=>$this->deviceSecret],JSON_THROW_ON_ERROR);$request=new Request('POST','/api/v1/devices/shortcut-sms',$body,[],[],[],['content-type'=>'application/json'],'127.0.0.1','');$auth=new DeviceAuthService($this->db,$this->devices,$this->crypto,$this->config);self::assertSame($this->device['id'],$auth->authenticateShortcut($request)['id']);}
    public function test_shortcut_rejects_wrong_secret():void{$request=new Request('POST','/api/v1/devices/shortcut-sms','{}',[],[],[],['x-device-key'=>$this->device['device_key'],'x-device-secret'=>'wrong-secret'],'127.0.0.1','');$auth=new DeviceAuthService($this->db,$this->devices,$this->crypto,$this->config);$this->expectException(\CardPay\Core\DomainException::class);$auth->authenticateShortcut($request);}
    public function test_payment_created_event_and_delivery_are_persisted():void{$this->db->execute('UPDATE cp_applications SET webhook_url=? WHERE id=?',['http://127.0.0.1:1/hook',$this->application['id']]);$this->application=$this->apps->find((int)$this->application['id']);$this->createPayment(1200000,'idem-webhook-01');self::assertSame(1,(int)$this->db->fetch("SELECT COUNT(*) value FROM cp_webhook_events WHERE event_type='payment.created'")['value']);$delivery=$this->db->fetch('SELECT * FROM cp_webhook_deliveries LIMIT 1');self::assertNotNull($delivery);self::assertContains($delivery['status'],['failed','exhausted']);}
}
